package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching employee records by department
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	dept := r.URL.Query().Get("dept")
	if dept == "" {
		http.Error(w, "dept parameter required", 400)
		return
	}

	// Sanitize: remove semicolons to prevent stacked queries
	dept = strings.ReplaceAll(dept, ";", "")

	// Build query - developer believes single-table SELECT is safe
	// since stacked queries are blocked
	query := fmt.Sprintf("SELECT id, name, email, salary FROM employees WHERE department = '%s'", dept)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	for rows.Next() {
		var id int
		var name, email string
		var salary float64
		if err := rows.Scan(&id, &name, &email, &salary); err != nil {
			continue
		}
		fmt.Fprintf(w, "%d | %s | %s | %.2f\n", id, name, email, salary)
	}
}

// healthHandler for load balancer health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

// updateProfileHandler - uses parameterized queries correctly
func updateProfileHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	r.ParseForm()
	name := r.FormValue("name")
	email := r.FormValue("email")
	id := r.FormValue("id")

	_, err := db.Exec("UPDATE employees SET name = $1, email = $2 WHERE id = $3", name, email, id)
	if err != nil {
		http.Error(w, "Update failed", 500)
		return
	}
	w.Write([]byte("updated"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/profile/update", updateProfileHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
